#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.19.2  -  the Privacy Policy and Terms of Use pages really open
#   * Why the links looked unchanged: the app already pointed at
#     https://aryanshahx.github.io/instantgram/privacy.html and terms.html, but GitHub
#     Pages was never switched on for the repo, so both links opened a 404 page.
#   * The pages are now complete .html files in docs/ (no Jekyll, no theme needed) and
#     a .github/workflows/pages.yml publishes them on every push.
#   * NEW text in both pages: how to delete your account and what is erased, the media
#     storage, and the music sources (Apple previews, Jamendo through Openverse).
#   * The app shows the very same words when there is no internet: lib/core/legal_text.dart
#     is generated from the same text by tools/gen_legal_docs.py.
# Run from the project root:   bash update_v1192_legal_pages.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="419f62b17dc343a29c91f597093c566324d860f0985b82b5a910f1def0e670e1"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/online_music_service.dart ] || { echo "ERROR: the free music update is not installed. Run update_v1171_free_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Publishing the pages with GitHub Pages (build-apk.yml is not touched)..."
mkdir -p .github/workflows
if [ -f .github/workflows/pages.yml ]; then
  echo "    .github/workflows/pages.yml is already there"
else
  cat > .github/workflows/pages.yml <<'YML'
name: Pages

on:
  push:
    branches: [main]
    paths: ['docs/**', '.github/workflows/pages.yml']
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: pages
  cancel-in-progress: true

jobs:
  deploy:
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/configure-pages@v5
      - uses: actions/upload-pages-artifact@v3
        with:
          path: docs
      - id: deployment
        uses: actions/deploy-pages@v4
YML
  echo "    .github/workflows/pages.yml written"
fi

echo "==> Adding the new packages to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1]
s = open(p).read()
add = ""
if not re.search(r"^[ \t]+audio_merge:", s, re.M):
    add += "  audio_merge:\n    path: packages/audio_merge\n"
if not re.search(r"^[ \t]+file_picker:", s, re.M):
    add += "  file_picker: 10.3.10\n"
if add:
    m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
    if not m:
        sys.exit("ERROR: no dependencies: section in pubspec.yaml")
    s = s[:m.end()] + add + s[m.end():]
    open(p, "w").write(s)
    print("    pubspec.yaml: added " + add.replace("\n", " ").strip())
else:
    print("    pubspec.yaml: already up to date")
PYX

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.19.2 is in place."
echo ""
echo "One thing to do once, in the browser:"
echo "  GitHub > instantgram > Settings > Pages > Build and deployment"
echo "  Source: GitHub Actions.   Save."
echo "Then push: the Pages action publishes docs/ and the links in the app open."
echo ""
echo "Good to know:"
echo "  * https://aryanshahx.github.io/instantgram/privacy.html"
echo "    https://aryanshahx.github.io/instantgram/terms.html"
echo "  * Both pages also open from Settings > About and from the sign-up screen."
echo "  * No internet, or Pages not switched on yet? The app shows the same text."
echo "  * Change the words later: edit tools/gen_legal_docs.py and run it once."
exit 0

